import {shouldEnhance} from './adaptive-policy.js';
import {paperComparisonHTML} from './paper-data.js';
import {analysisPage} from './analysis-ui.js';
import {canUploadSession,recordClass,uploadTrial} from './upload-policy.js';
import {projectCode} from './project.js';
import {World} from './scene.js';
import {studies,tiers,makeTrials,evaluateResponse,summarize,slope,db,download,csv} from './core.js';
import {eye,startEye,stopEye,calibrate} from './eye.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');let worlds=[],runner=null,lastSession=null;
let selectedTier=localStorage.getItem('starparcel.tier')||'quick';if(!tiers[selectedTier])selectedTier='quick';
function tierPicker(){return '<label class="field">任务长度（三项合计）<select class="tier-picker">'+Object.entries(tiers).map(([id,t])=>'<option value="'+id+'" '+(id===selectedTier?'selected':'')+'>'+t.name+' · '+t.duration+'</option>').join('')+'</select></label><p class="small">时长为三项任务的合计估计，含练习，不含首次摄像头校准；随反应速度变化。低、中、高三档的任务数量不同。低档驾驶 16 次，地图与旋转各 12 次；练习分别 8、6、6 次。只有高档满足当前细分条件的正式试次数要求。</p>';}
function bindTier(){document.querySelectorAll('.tier-picker').forEach(el=>el.onchange=()=>{selectedTier=el.value;localStorage.setItem('starparcel.tier',selectedTier);route();});}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function dialog(html){$('#modal-body').innerHTML=html;modal.showModal();}
$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
function world(el,type){try{const w=new World(el,type);worlds.push(w);return w;}catch{el.innerHTML=`<div class="empty"><img src="assets/scene-preview.png" style="max-width:100%;max-height:280px" alt="兔兔宇航员与浮空小岛"><p>三维渲染暂不可用，请在支持 WebGL 的浏览器中打开。</p></div>`;return null;}}
function eyeStatus(){$('#eye-status').textContent=eye.ready?'眼动已校准':eye.mode==='camera'?'需要校准':'连接眼动';$('#eye-open').classList.toggle('connected',eye.ready);}
function openEye(){dialog(`<span class="badge">CAMERA · 眼动准备</span><h2 class="spaced">让好奇心，有迹可循。</h2><p>使用普通摄像头估计屏幕注视位置。请坐在光线均匀的位置，屏幕距眼睛约一臂，保持头部稳定。</p><div class="notice mint">视频在本机浏览器处理，不上传录像。记录的是注视坐标、时间与实验反应；数据默认仅保存在当前浏览器。</div><p>摄像头估计适合较大的兴趣区。校准后会记录验证误差，误差大小不限制进入实验；仍需实际获得眼动样本。</p><label class="check-row"><input type="checkbox" id="eye-consent">我理解并同意使用摄像头进行本实验的眼动估计，可随时关闭。</label><div class="stack"><button class="primary" id="camera-start">${eye.mode==='camera'?'重新校准':'开启摄像头并校准'} ↗</button><button class="secondary" id="camera-stop">关闭摄像头</button></div><p id="camera-message" class="small">九点校准，每点点击 5 次；随后进行独立验证。</p>`);$('#camera-start').onclick=async()=>{if(!$('#eye-consent').checked){toast('请先阅读并勾选摄像头知情同意。');return;}const b=$('#camera-start');b.disabled=true;$('#camera-message').textContent='正在加载本地眼动模型，请允许摄像头访问…';try{if(eye.mode!=='camera')await startEye();modal.close();await calibrate();eyeStatus();toast(`校准完成，平均误差 ${eye.calibration.meanError} px（仅记录，不拦截）。`);}catch(e){eyeStatus();if(modal.open){$('#camera-message').textContent=e.message;b.disabled=false;}else{toast(e.message);}}};$('#camera-stop').onclick=()=>{stopEye();eyeStatus();modal.close();toast('摄像头已关闭。');};}
$('#eye-open').onclick=openEye;window.addEventListener('eyeinvalid',()=>{eyeStatus();toast('窗口尺寸发生变化，请重新校准眼动。');runner?.pause('窗口尺寸变化，当前试次已标为无效。请重新校准后继续。');});
const card=(s,i)=>`<article class="task-card"><a href="#study/${s.id}" aria-label="了解${s.title}"><div class="card-art ${s.color}" id="card-${s.id}"><span class="card-tag">${s.tag}</span><span class="card-num">0${i+1}</span></div></a><div class="card-body"><a class="card-title" href="#study/${s.id}"><h3>${s.title}</h3><span>${s.icon}</span></a><div class="card-sub">${s.english}</div><p>${s.brief}</p><div class="card-bottom"><span>${tiers[selectedTier].counts[s.id]} 试次 · 3D 交互</span><a class="card-start" href="#study/${s.id}">领取任务 ↗</a></div></div></article>`;
function home(){app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A SMALL JOURNEY INTO YOUR MIND</div><h1>把好奇心，<br>送进<em>你的宇宙。</em></h1><p>跟着兔兔快递员，一起看见注意的轨迹。<br>在三个小小的 3D 任务里，探索看哪里、<br>怎么认路，以及脑海中的旋转。</p><div class="hero-actions"><a class="primary" href="#study/drive">开启第一站 <span>↗</span></a><a class="text-link" href="#concepts">先翻翻概念手册 ↓</a></div><div class="hero-details"><span><b>✦</b> 3 个经典研究</span><span><b>◎</b> 摄像头眼动</span><span><b>⌁</b> ${tiers[selectedTier].duration}</span></div></div><div class="hero-art" id="hero-world" role="img" aria-label="兔兔宇航员、火箭和快递包裹的三维浮空小岛"><div class="orbit-label one"><i>✧</i> 下一站：你的注意力</div><div class="orbit-label two"><i>●</i> 兔兔已准备出发</div></div></section><aside class="strip"><div><strong>◎ 第一次来？先和眼动打个招呼。</strong><p>任务使用摄像头采集；请先完成校准，结束后自动上传已同意的摘要。</p></div><button class="text-link" id="strip-eye">准备眼动 ↗</button></aside><section id="missions"><div class="panel spaced">${tierPicker()}</div><div class="section-head"><div><h2>今天，探索哪一站？</h2><p>一份任务，一点发现。按你的节奏慢慢来。</p></div><span class="micro">MISSION BOARD / 01—03</span></div><div class="cards">${Object.values(studies).map(card).join('')}</div></section><section class="journey"><h3>你的探索路线</h3><div class="steps"><span><b>01</b>了解任务</span><span><b>02</b>校准与练习</span><span><b>03</b>开始观测</span><span><b>04</b>发现规律</span></div></section>`;world($('#hero-world'),'hero');Object.values(studies).forEach(s=>world($('#card-'+s.id),s.id));$('#strip-eye').onclick=openEye;}
function study(id){const base=studies[id];if(!base)return home();const s={...base,count:tiers[selectedTier].counts[id]};app.innerHTML=`<section class="page-head"><a class="small" href="#home">← 返回任务板</a><div class="eyebrow spaced">${s.english}</div><h1>${s.title}</h1><p>${s.question} 这次，让我们亲自试试看。</p></section><div class="experiment-layout"><div><div class="exp-preview" id="study-world"></div><div class="panel spaced"><span class="badge">任务简报</span><h3 class="spaced">${s.question}</h3><p class="spaced">${s.description}</p><div class="info-grid"><div><small>理论</small>${s.theory}</div><div><small>正式试次</small>${s.count} 次</div><div><small>准备练习</small>${s.practice} 次</div></div><h3>我们比较什么</h3>${s.conditions.map((c,i)=>`<div class="condition"><strong>0${i+1} · ${c}</strong><p>${i===s.conditions.length-1?'新增或比较条件，用数据检验设计想法。':'基线比较条件，保持相同任务规则。'}</p></div>`).join('')}<div class="notice mint">本次选择：${tiers[selectedTier].name}。先做 ${s.practice} 次练习，再完成总共 ${s.count} 次任务；不是每个条件做 ${s.count} 次。${tiers[selectedTier].eligible?'本档位按完整条件平衡设计。':'低中档用于体验或试测，不代表每个细分条件有 10 次。'}</div><details><summary>查看高档完整实验设计</summary><p class="spaced">${s.design}</p></details><div class="notice">待确认的预测：${s.prediction}<br>本页是经典研究的主题改编；不等同原始研究的完整复现。</div><p class="small">研究出处：<a href="${s.doi}" target="_blank" rel="noopener">${s.source} ↗</a></p></div></div><aside><div class="panel"><h3>领取你的任务</h3>${tierPicker()}<div class="notice">${tiers[selectedTier].eligible?'高档：每个细分条件至少 10 次，可用于正式采集。':'短版：用于体验或眼动试测，不满足每分析单元至少 10 次。'}</div><label class="field">匿名编号<input id="participant" placeholder="例如 P01，不填姓名或学号" maxlength="24" autocomplete="off"></label><label class="field">探索模式<select id="run-mode"><option value="formal">${tiers[selectedTier].eligible?'正式采集 · 需摄像头校准':'摄像头试测 · 试次数不足'}</option></select></label><label class="check-row"><input id="participation-consent" type="checkbox">我自愿参与摄像头眼动采集，可随时退出；完成后将匿名编号、行为与眼动摘要自动上传到课程项目 ${escape(projectCode())}，完整眼动坐标保存在本机。</label><button id="begin" class="primary full">先做 ${s.practice} 次练习 ↗</button><button id="study-eye" class="text-link full">${eye.ready?'◎ 校准已完成':'◎ 准备摄像头眼动'}</button><p id="start-message" class="small">练习有反馈，正式任务不提示答案。正式采集建议使用电脑。</p></div><div class="panel"><span class="badge">小小实验须知</span><p class="spaced">保持窗口大小与坐姿稳定。切换标签页、调整窗口或长时间丢失眼动时会暂停并标记当前试次。</p><p class="spaced">所有预测需在正式收数前由项目作者确认并提交记录。</p><p class="mobile-note spaced">手机可预览，正式采集请使用电脑。</p></div></aside></div>`;const w=world($('#study-world'),id);if(id==='rotate')w?.setRotation(1,60,false,true);$('#study-eye').onclick=openEye;$('#begin').onclick=()=>{const p=$('#participant').value.trim(),mode=$('#run-mode').value;if(!p||!/^[\p{L}\p{N}_-]{1,24}$/u.test(p)){toast('请填写 1–24 位匿名编号，仅用字母、数字、下划线或短横线。');return;}if(!$('#participation-consent').checked){toast('请先勾选参与同意。');return;}if(mode==='formal'&&(!eye.ready||!eye.last||performance.now()-eye.last.t>2000)){toast('摄像头采集需要完成校准且有有效眼动信号；误差大小不限制进入。');openEye();return;}disposeWorlds();runner=new Experiment(s,p,mode);runner.start(true);};}
function disposeWorlds(){worlds.forEach(w=>w.dispose());worlds=[];}
class Experiment{
 constructor(s,participant,mode){this.tier=selectedTier;this.s=s;this.participant=participant;this.mode=mode;this.rows=[];this.index=0;this.timers=[];this.live=false;this.paused=false;this.key=e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyF','KeyJ','KeyK'].includes(e.code)){e.preventDefault();if(!e.repeat)this.answer(({Space:'space',ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',KeyF:'f',KeyJ:'j',KeyK:'k'})[e.code]);}};this.visibility=()=>{if(document.hidden)this.pause('你离开了页面，当前试次已标记无效。回到稳定坐姿后继续。');};document.addEventListener('keydown',this.key);document.addEventListener('visibilitychange',this.visibility);}
 timer(fn,ms){const id=setTimeout(fn,ms);this.timers.push(id);return id;}
 clear(){this.timers.forEach(clearTimeout);this.timers=[];this.live=false;eye.active=false;}
 start(practice){document.body.classList.add('running');window.scrollTo(0,0);this.practice=practice;this.index=0;this.trials=makeTrials(this.s.id,practice,this.tier);app.innerHTML=`<div class="run-mode"><div class="run-top"><a href="#study/${this.s.id}" id="run-back">← 退出任务</a><span class="badge">${this.mode==='formal'?(tiers[this.tier].eligible?'摄像头正式采集':'摄像头试测 · 试次不足'):'自由体验 · 演示数据'} / ${practice?'练习':'任务阶段'}</span><span id="run-counter"></span></div><h2>${this.s.title}</h2><p class="small spaced">${this.s.description}</p><p class="small">${this.practice?'本轮练习':'本轮任务'}总共 ${this.trials.length} 次。${this.practice?'练习有反馈，不计入结果。':'任务不提示答案，结果会保存在本机。'}</p><div class="progress spaced"><i id="run-progress"></i></div><div class="experiment-stage" id="run-world"><div class="stage-label" id="stage-label"></div>${this.s.id==='drive'?'<div class="stage-hud"><div class="hud" id="road-hud" aria-hidden="true"><b></b></div><div class="hud" id="panel-hud">货舱温度<div class="dial-face"><i></i><b>42°C</b></div>J · 温度告警</div><div class="hud" id="speed-hud">飞行速度<div class="dial-face"><i></i><b>64 km/h</b></div>K · 超过 80 降速 · 1 分</div></div>':''}${this.s.id==='map'?'<div class="minimap" id="mini-map"></div><div class="heading-indicator" id="heading-label"></div>':''}</div><div class="run-prompt" id="run-prompt">准备好，看看下一份任务。</div><div class="response-row">${this.s.id==='drive'?'<button class="secondary" data-answer="space">空格 · 同向火箭</button><button class="secondary" data-answer="j">J · 温度告警</button><button class="secondary" data-answer="k">K · 超速降速</button>':this.s.id==='map'?['left','up','right','down'].map((a,i)=>`<button class="secondary" data-answer="${a}">${['← 左','↑ 前','→ 右','↓ 后'][i]}</button>`).join(''):'<button class="secondary" data-answer="f">F · 同一形状</button><button class="secondary" data-answer="j">J · 镜像形状</button>'}</div><p class="feedback" id="feedback" aria-live="polite"></p><div id="pause-controls"></div></div>`;this.w=world($('#run-world'),this.s.id);if(!this.w){this.dispose();toast('无法启动三维实验，请更换支持 WebGL 的浏览器。');return;}if(this.s.id==='drive'){const hud=$('#run-world .stage-hud');$('#run-world').after(hud);}document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>this.answer(b.dataset.answer));this.next();}
 next(){this.clear();if(this.index>=this.trials.length){this.finish();return;}this.paused=false;this.responded=false;this.anticipations=0;this.trial=this.trials[this.index];const t=this.trial;if(this.s.id==='drive'&&this.announcedBlock!==`${this.practice}/${t.block}`){this.announcedBlock=`${this.practice}/${t.block}`;this.live=false;this.paused=true;$('#run-prompt').textContent=`第 ${t.block} 块：${t.priority==='road'?'道路':'仪表'}优先。该类事件答对得 3 分，另一道路/温度事件得 2 分，超速始终 1 分，对向火箭不响应。`;$('#pause-controls').innerHTML='<div class="response-row"><button class="primary" id="block-start">我已理解本块优先级，开始 →</button></div>';$('#block-start').onclick=()=>{$('#pause-controls').innerHTML='';this.next();};return;}$('#run-counter').textContent=`${this.index+1} / ${this.trials.length}`;$('#run-progress').style.width=this.index/this.trials.length*100+'%';$('#feedback').textContent='';$('#stage-label').textContent=this.s.conditions[t.cond]+(this.s.id==='drive'?` · ${t.priority==='road'?'道路':'仪表'}优先（3 分），其他道路/温度 2 分，超速 1 分`:'');$('#run-prompt').textContent=this.s.id==='drive'?'保持观察，信号可能出现在不同位置。':this.s.id==='map'?'下一站，相对你在哪个方向？':'这两个包裹，可以通过旋转重合吗？';eye.samples=[];this.sampleStart=performance.now();if(this.s.id==='drive'){this.instrumentSeen=false;this.firstInstrumentLook=null;this.adaptiveShown=false;this.adaptiveDelay=null;this.w.setHazard(null);$('#panel-hud i').style.rotate='-50deg';$('#speed-hud i').style.rotate='-30deg';$('#road-hud').classList.remove('alert');$('#road-hud b').textContent='';$('#panel-hud').classList.remove('alert');$('#panel-hud b').textContent='42°C';$('#speed-hud').classList.remove('alert');$('#speed-hud b').textContent='64 km/h';this.onset=null;this.live=true;this.timer(()=>{this.w.setHazard(t.event,t.cond===1);if(t.event==='road'){$('#road-hud b').textContent='';if(t.cond===1)$('#road-hud').classList.add('alert');}else if(t.event==='panel'){$('#panel-hud b').textContent='86°C';$('#panel-hud i').style.rotate='50deg';}else if(t.event==='speed'){$('#speed-hud b').textContent='96 km/h';$('#speed-hud i').style.rotate='65deg';}else{$('#road-hud b').textContent='';}requestAnimationFrame(()=>{if(!this.live)return;this.onset=performance.now();this.monitorInstrument();this.timer(()=>this.answer(null),t.timeout);});},t.delay);}else{if(this.s.id==='map'){this.mapSeen=false;this.firstMapLook=null;this.mapAdaptiveShown=false;this.mapAdaptiveDelay=null;this.w.setMap(t.heading,t.bearing);this.drawMap(t);}else this.w.setRotation(t.shape,t.angle,t.mirror,t.cond===1);this.live=false;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(this.paused)return;this.onset=performance.now();this.live=true;if(this.s.id==='map')this.monitorMap();this.timer(()=>this.answer(null),t.timeout);}));}eye.active=this.mode==='formal';if(this.mode==='formal')this.watchEye();}
 monitorInstrument(){if(!this.live||this.responded||this.paused)return;const event=this.trial.event;if(!['panel','speed'].includes(event))return;const el=$(event==='panel'?'#panel-hud':'#speed-hud'),p=eye.last,r=el.getBoundingClientRect(),elapsed=performance.now()-this.onset;if(p&&performance.now()-p.t<200){if(p.x>=r.left&&p.x<=r.right&&p.y>=r.top&&p.y<=r.bottom){if(!this.instrumentSeen)this.firstInstrumentLook=Math.round(elapsed);this.instrumentSeen=true;el.classList.remove('alert');}else if(shouldEnhance({condition:this.trial.cond,event,elapsed,looked:this.instrumentSeen,shown:this.adaptiveShown,signalFresh:true})){this.adaptiveShown=true;this.adaptiveDelay=Math.round(elapsed);el.classList.add('alert');}}this.timer(()=>this.monitorInstrument(),100);}
 monitorMap(){if(!this.live||this.responded||this.paused)return;const el=$('#mini-map'),p=eye.last,r=el.getBoundingClientRect(),elapsed=performance.now()-this.onset;if(p&&performance.now()-p.t<200){if(p.x>=r.left&&p.x<=r.right&&p.y>=r.top&&p.y<=r.bottom){if(!this.mapSeen)this.firstMapLook=Math.round(elapsed);this.mapSeen=true;}else if(shouldEnhance({condition:this.trial.cond===2?1:0,event:'map',elapsed,looked:this.mapSeen,shown:this.mapAdaptiveShown,signalFresh:true})){this.mapAdaptiveShown=true;this.mapAdaptiveDelay=Math.round(elapsed);el.classList.add('adaptive-map');}}this.timer(()=>this.monitorMap(),100);}
 watchEye(){this.timer(()=>{if(!this.live)return;if(!eye.ready||!eye.last||performance.now()-eye.last.t>2500){this.pause('眼动信号丢失，当前试次已标记无效。请调整坐姿，必要时重新校准。');return;}this.watchEye();},700);}
 drawMap(t){const r=t.cond===1?-t.heading:0,rad=t.bearing*Math.PI/180,x=75+Math.sin(rad)*43,y=75-Math.cos(rad)*43;$('#mini-map').classList.remove('adaptive-map');$('#mini-map').innerHTML=`<span class="north">${t.cond===1?'航向向上':'N 北'}</span><svg viewBox="0 0 150 150" aria-label="目标和航向的小地图"><g transform="rotate(${r} 75 75)"><path d="M75 17V133M17 75H133" stroke="#d5ddc9" stroke-width="15"/><circle cx="33" cy="33" r="9" fill="#c9b4dc"/><circle cx="118" cy="118" r="9" fill="#bfd3af"/>${t.cond===2?`<path class="view-sector" d="M75 75 L49 25 Q75 6 101 25 Z" fill="#87b99a" opacity=".15" transform="rotate(${t.heading} 75 75)"/>`:''}<circle cx="${x}" cy="${y}" r="8" fill="#e59b65"/><path d="M75 62 L84 84 L75 80 L66 84 Z" fill="#356d55" transform="rotate(${t.heading} 75 75)"/></g></svg>`;$('#heading-label').textContent=`当前航向 ${t.heading}° · 橘点是下一站`;}
 answer(answer){if(!this.live||this.responded||this.paused)return;if(this.s.id==='drive'&&this.onset===null){if(answer){this.anticipations++;$('#feedback').textContent=this.practice?'信号尚未出现，请不要提前按键。':'';}return;}this.responded=true;const rt=answer===null?null:Math.round(performance.now()-this.onset),evaluation=evaluateResponse(this.trial,answer,rt),anticipatory=Boolean(evaluation.anticipatory),correct=Boolean(evaluation.correct);this.store({...evaluation,earlyPresses:this.anticipations,invalid:0});this.clear();$('#feedback').textContent=this.practice?(correct?'✓ 做得好，继续下一份任务。':answer===null?'漏报：应响应事件未处理。':anticipatory?'反应过早，请看清任务后作答。':'这次没有答对，按任务规则再试试。'):'已记录';this.index++;this.timer(()=>this.next(),this.practice?1100:450);}
 store(extra){if(this.practice)return;const samples=eye.samples.slice(),end=performance.now(),coverage=Math.min(1,samples.length*66/Math.max(1,end-this.sampleStart));const rect=$('#run-world').getBoundingClientRect(),toRect=e=>e.getBoundingClientRect().toJSON();const regions=this.s.id==='drive'?{road_instrument:toRect($('#road-hud')),cargo_instrument:toRect($('#panel-hud')),speed_instrument:toRect($('#speed-hud')),road:rect.toJSON()}:this.s.id==='map'?{map:toRect($('#mini-map')),scene:rect.toJSON()}:{left_object:{x:rect.x,y:rect.y,width:rect.width/2,height:rect.height},right_object:{x:rect.x+rect.width/2,y:rect.y,width:rect.width/2,height:rect.height}};const counts={};for(const p of samples){const x=p.x*innerWidth,y=p.y*innerHeight;const area=Object.entries(regions).find(([name,r])=>x>=r.x&&x<=r.x+r.width&&y>=r.y&&y<=r.y+r.height)?.[0]||'outside';counts[area]=(counts[area]||0)+1;}this.rows.push({...this.trial,...extra,...(this.s.id==='map'?{map_sampled:this.mapSeen??false,first_map_sample_ms:this.firstMapLook??null,adaptive_cue_shown:this.mapAdaptiveShown??false,adaptive_cue_delay_ms:this.mapAdaptiveDelay??null}:{}),...(this.s.id==='drive'?{adaptive_cue_shown:this.adaptiveShown??false,adaptive_cue_delay_ms:this.adaptiveDelay??null,instrument_sampled:this.instrumentSeen??false,first_instrument_sample_ms:this.firstInstrumentLook??null}:{}),index:this.index+1,condition:this.s.conditions[this.trial.cond],gaze_samples:samples.length,coverage:+coverage.toFixed(3),aoi:counts,aoi_rects:regions,gaze:samples.map(p=>({...p,t:Math.round(p.t-this.sampleStart)})),viewport:{w:innerWidth,h:innerHeight},display_rect:$('#run-world').getBoundingClientRect().toJSON()});}
 pause(reason){if(this.paused)return;this.paused=true;if(this.live&&!this.responded){this.store({response:'interrupted',rt:null,correct:0,invalid:1,reason});this.trials.push({...this.trial});this.index++;}this.clear();$('#feedback').textContent=reason;$('#pause-controls').innerHTML='<div class="response-row"><button class="secondary" id="pause-eye">重新校准</button><button class="primary" id="resume-run">继续下一试次 →</button></div>';$('#pause-eye').onclick=openEye;$('#resume-run').onclick=()=>{if(this.mode==='formal'&&(!eye.ready||!eye.last||performance.now()-eye.last.t>1500)){toast('请先恢复有效眼动信号或重新校准。');return;}$('#pause-controls').innerHTML='';this.next();};}
 finish(){this.clear();if(this.practice){this.w.dispose();$('#run-world').innerHTML='<div class="empty"><div class="icon">✧</div><h2>练习完成，准备启航。</h2><p>接下来不再提示答案。随时可以退出任务。</p><button id="start-formal" class="primary">开始'+this.trialsCount()+'次任务 →</button></div>';$('#run-prompt').textContent='';$('#feedback').textContent='';$('.response-row').innerHTML='';$('#start-formal').onclick=()=>{if(this.mode==='formal'&&!eye.ready){openEye();return;}disposeWorlds();this.start(false);};return;}const session={id:crypto.randomUUID(),participant:this.participant,experiment:this.s.id,mode:this.mode,created:new Date().toISOString(),calibration:this.mode==='formal'?eye.calibration:null,tier:this.tier,courseEligible:tiers[this.tier].eligible,plannedTrials:tiers[this.tier].counts[this.s.id],collectionPolicy:'tiered-practice-capped-error-record-only-2026-11-02',autoUpload:this.mode==='formal',uploadProject:projectCode(),protocol:this.s.id==='drive'?'starparcel-v4-adaptive-2026-11-03':this.s.id==='map'?'starparcel-v3-map-adaptive-2026-11-03':'starparcel-v3-common-frame-2026-11-03',trials:this.rows};lastSession=session;const saved=db.add(session);this.dispose();location.hash='#session/'+session.id;if(!saved)toast('浏览器存储空间不足，本次结果仅保留在当前页面，请立即导出。');}
 trialsCount(){return this.s.count;}
 dispose(){document.body.classList.remove('running');this.clear();document.removeEventListener('keydown',this.key);document.removeEventListener('visibilitychange',this.visibility);runner=null;}
}
function concepts(){app.innerHTML=`<section class="page-head"><div class="eyebrow">FIELD NOTES</div><h1>好奇心的概念手册。</h1><p>从一次小任务，到一个可检验的心理学问题。拨动参数，看看理论在说什么。</p></section><div class="concept-grid"><article class="concept-card"><div class="symbol">◉</div><span class="badge">01 · SEEV</span><h3 class="spaced">什么决定你看哪里</h3><p>显著性 S、扫描努力 EF、期望 EX 和价值 V 共同影响注意分配。醒目的东西，不一定是任务中最重要的东西。</p><div class="concept-demo"><label>道路任务价值 V <b id="seev-value">5</b><input id="seev-range" type="range" min="1" max="10" value="5"></label><p id="seev-prediction">示意分配：道路 50% · 仪表 50%</p></div><a class="text-link" href="#study/drive">去驾驶舱检验 ↗</a></article><article class="concept-card"><div class="symbol">⌁</div><span class="badge">02 · FRAME OF REFERENCE</span><h3 class="spaced">地图和你，谁在转</h3><p>北向上让环境参照系稳定，航向向上便于匹配前方视野。哪一种更好，取决于你在判断转向还是学习整体布局。</p><div class="concept-demo"><label>当前航向 <b id="heading-value">90°</b><input id="heading-range" type="range" min="0" max="270" step="90" value="90"></label><p id="heading-demo">北方在你左边。</p></div><a class="text-link" href="#study/map">去星图找方向 ↗</a></article><article class="concept-card"><div class="symbol">⤨</div><span class="badge">03 · MENTAL ROTATION</span><h3 class="spaced">在脑海里转个弯</h3><p>角度差越大，比较同形物体通常需要越长时间。正式任务中的物体保持静止，让旋转发生在你的脑海里。</p><div class="concept-demo"><label>物体角度差 <b id="angle-value">60°</b><input id="angle-range" type="range" min="0" max="180" step="30" value="60"></label><p>可视化演示 · 不产生实验数据</p></div><a class="text-link" href="#study/rotate">去包裹站试试 ↗</a></article></div><div class="exp-preview" id="concept-world" style="margin-bottom:30px;height:320px"></div><div class="notice">上方 SEEV 百分比是简化的教学示意（道路价值 / 总价值），不是原论文拟合模型，也不是你的实测结果。</div><p class="small" style="margin-bottom:40px">眼动 ≠ 全部注意。未注视某区域不代表完全没有加工，注视某物也不保证觉察或理解。</p>`;const w=world($('#concept-world'),'rotate');w?.setRotation(0,60,false,false);$('#seev-range').oninput=e=>{$('#seev-value').textContent=e.target.value;const n=Math.round(+e.target.value/(+e.target.value+5)*100);$('#seev-prediction').textContent=`示意分配：道路 ${n}% · 仪表 ${100-n}%`;};$('#heading-range').oninput=e=>{$('#heading-value').textContent=e.target.value+'°';$('#heading-demo').textContent=['北方在你前方。','北方在你左边。','北方在你后方。','北方在你右边。'][+e.target.value/90];};$('#angle-range').oninput=e=>{$('#angle-value').textContent=e.target.value+'°';w?.setRotation(0,+e.target.value,false,false);};}
function flatRows(s){return s.trials.map(t=>{const {gaze,aoi,aoi_rects,viewport,display_rect,...rest}=t;return{session:s.id,participant:s.participant,experiment:s.experiment,mode:s.mode,calibration_error:s.calibration?.meanError??null,calibration_quality_flag:s.calibration?.qualityPass??null,error_gate_enabled:s.calibration?.errorGateEnabled??null,tier:s.tier||'legacy',courseEligible:s.courseEligible??false,protocol:s.protocol,collectionPolicy:s.collectionPolicy,created:s.created,...rest,aoi:JSON.stringify(aoi),width:viewport.w,height:viewport.h,display_rect:JSON.stringify(display_rect)};});}
function results(){const sessions=db.read(),formal=sessions.filter(s=>s.mode==='formal'&&s.courseEligible);app.innerHTML=`<div class="inline-actions spaced"><a class="primary" href="#analysis">效应、原文对照与改进检验 ↗</a></div><section class="page-head"><div class="eyebrow">YOUR OBSERVATORY</div><h1>每一次探索，都有回声。</h1><p>结果仅来自当前浏览器的真实任务记录。自由体验与正式采集分开显示。</p></section><div class="stats-grid"><div class="stat"><b>${sessions.length}</b><span>已完成任务</span></div><div class="stat"><b>${formal.length}</b><span>正式采集记录</span></div><div class="stat"><b>${new Set(formal.map(s=>s.participant)).size}</b><span>本机正式被试编号</span></div><div class="stat"><b>${sessions.reduce((n,s)=>n+s.trials.length,0)}</b><span>已记录试次</span></div></div>${sessions.length?`<div class="panel"><div style="overflow:auto"><table class="result-table"><thead><tr><th>任务</th><th>编号</th><th>模式</th><th>正确率</th><th>正确 RT</th><th></th></tr></thead><tbody>${[...sessions].reverse().map(s=>{const r=summarize(s.trials);return`<tr><td>${studies[s.experiment].title}</td><td>${escape(s.participant)}</td><td>${s.mode==='formal'?(s.courseEligible?'正式':'试测'):'体验'}</td><td>${r.accuracy}%</td><td>${r.rt??'—'} ms</td><td><a href="#session/${s.id}">查看 ↗</a></td></tr>`;}).join('')}</tbody></table></div><div class="result-actions"><button class="secondary" id="all-csv">导出全部行为 CSV</button><button class="secondary" id="all-json">导出完整 JSON</button></div></div>`:'<div class="panel empty"><div class="icon">✧</div><h2>观测本，等你写下第一笔。</h2><p>完成任意任务后，条件对比和注视轨迹会出现在这里。</p><a class="primary" href="#home">去领取任务 ↗</a></div>'}<div class="panel"><h3>连接课程收数接口</h3><p class="spaced">项目码需要你用学号在课程网站创建。下载密钥无需填入本页。新任务在开始前同意后自动上传；低中档保留试测标记，旧记录需手动确认上传。</p><label class="field">6 位项目码<input id="project-code" maxlength="6" placeholder="例如 ABC234" autocomplete="off"></label><p class="small">上传入口在单次结果页。眼动完整坐标保留于 JSON；课程接口只提交行为试次与眼动摘要。</p><a class="text-link" target="_blank" rel="noopener" href="https://attention-lab-production.up.railway.app/hw2">打开课程项目管理 ↗</a></div>`;if(sessions.length){$('#all-csv').onclick=()=>download('starparcel-all.csv',csv(sessions.flatMap(flatRows)),'text/csv;charset=utf-8');$('#all-json').onclick=()=>download('starparcel-all.json',JSON.stringify(sessions,null,2));}$('#project-code').value=projectCode();$('#project-code').onchange=e=>{const p=e.target.value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(p)){toast('项目码应为 6 位字母或数字。');return;}localStorage.setItem('starparcel.project',p);toast('项目码已保存到本机。');};}
function sessionPage(id){const s=db.read().find(s=>s.id===id)||(lastSession?.id===id?lastSession:null);if(!s)return results();const study=studies[s.experiment],sum=summarize(s.trials),groups=study.conditions.map((name,i)=>({name,...summarize(s.trials.filter(t=>t.cond===i))})),max=Math.max(...groups.map(g=>g.rt||0),1),coverage=s.trials.reduce((n,t)=>n+t.coverage,0)/Math.max(1,s.trials.length);app.innerHTML=`<section class="page-head"><a class="small" href="#results">← 我的观测</a><div class="eyebrow spaced">MISSION COMPLETE</div><h1>送达！这次你发现了什么？</h1><p>${study.title} · ${escape(s.participant)} · ${s.mode==='formal'?(s.courseEligible?'正式采集':'摄像头试测，试次数不足'):'自由体验，不能计入正式结果'} · ${new Date(s.created).toLocaleString('zh-CN')}</p></section><div class="stats-grid"><div class="stat"><b>${sum.accuracy}%</b><span>有效试次正确率</span></div><div class="stat"><b>${sum.rt??'—'}<small> ms</small></b><span>正确反应平均时间</span></div><div class="stat"><b>${sum.n}</b><span>有效试次 · 中断 ${sum.invalid} 次</span></div><div class="stat"><b>${s.mode==='formal'?Math.round(coverage*100)+'%':'—'}</b><span>近似眼动采样覆盖率</span></div></div><div class="panel"><p class="small">协议版本：${escape(s.protocol||'v1')} · 档位：${escape(tiers[s.tier]?.name||'旧版')}。不同档位、版本请分开分析。</p><h3>不同条件下，反应有何变化？</h3><p>仅纳入有效、正确且非过早的反应；超时与错误仍计入正确率。</p><div class="chart">${groups.map(g=>`<div class="bar-row"><span>${g.name}</span><div class="bar-track"><div class="bar-fill" style="width:${g.rt?g.rt/max*100:0}%"></div></div><strong>${g.rt??'—'} ms</strong></div>`).join('')}</div><div style="overflow:auto"><table class="result-table"><thead><tr><th>条件</th><th>有效试次</th><th>正确率</th><th>正确平均 RT</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${g.name}</td><td>${g.n}</td><td>${g.accuracy}%</td><td>${g.rt??'—'} ms</td></tr>`).join('')}</tbody></table></div><div class="notice mint">${effectText(s,groups)}<br>单次结果仅作描述，不代表已复现原论文，也不代表改进已通过统计检验。</div></div>${paperComparisonHTML([s],s.experiment)}<div class="panel"><h3>你的注视，落在了哪里？</h3><p class="spaced">${s.mode==='formal'?'以下为整屏归一化注视点分布，跨试次叠加；不是三维物体表面的精确热图。':'体验模式未记录摄像头眼动，不能生成真实注视热图。'}</p><div class="heatmap spaced"><canvas id="heat-canvas"></canvas><span class="heat-label">${s.mode==='formal'?'屏幕坐标叠加 · 仅供质量与粗区域观察':'尚无眼动数据'}</span></div>${s.calibration?`<p class="small spaced">校准误差 ${s.calibration.meanError} px · 参考线 ${s.calibration.threshold} px（不作为进入限制）。覆盖率由采样数近似估计，不作为精确帧率或注视检测指标。</p>`:''}</div><div class="panel"><h3>把这次发现带走</h3><div class="result-actions"><button class="secondary" id="one-csv">行为数据 CSV ↓</button><button class="secondary" id="one-json">含眼动的完整 JSON ↓</button>${canUploadSession(s)?'<button class="primary" id="upload-session">上传到课程项目 ↗</button>':''}</div><p class="small">完整 JSON 包含每试次眼动坐标、时间、屏幕尺寸与刺激区位置，供后续分析。本机先保存完整记录；本次已同意的采集会自动上传摘要，实际状态见下方。</p><div id="upload-state" class="small spaced"></div></div><div class="inline-actions" style="margin-bottom:45px"><a class="primary" href="#home">继续下一站 ↗</a><a class="secondary" href="#concepts">看看背后的理论</a><a class="secondary" href="#analysis">多人效应分析 ↗</a></div>`;$('#one-csv').onclick=()=>download(`starparcel-${s.experiment}-${s.participant}.csv`,csv(flatRows(s)),'text/csv;charset=utf-8');$('#one-json').onclick=()=>download(`starparcel-${s.experiment}-${s.participant}.json`,JSON.stringify(s,null,2));$('#upload-session')?.addEventListener('click',()=>confirmUpload(s));if(s.mode==='formal')drawHeat(s);const up=uploadStatuses()[s.id];if(up?.state==='success')$('#upload-state').textContent='上传成功 · '+up.record;else if(s.autoUpload&&!up)sendCourse(s);else if(up)$('#upload-state').textContent='上传未确认：'+(up.error||'上次请求未取得回执')+'；请先核验老师后台，避免重复提交。';}
function effectText(s,g){
 const f=v=>v===null?'不足以计算':v.toFixed(2);
 if(s.experiment==='rotate'){
  // The original RT–angle prediction concerns same-object rotations. Mirrors are separate.
  const same=s.trials.filter(t=>!t.mirror),a=slope(same.filter(t=>t.cond===0)),b=slope(same.filter(t=>t.cond===1));
  const x=summarize(same.filter(t=>t.cond===0)),y=summarize(same.filter(t=>t.cond===1));
  return '同形试次 RT–角度斜率：无坐标轴 '+f(a)+' ms/°；有坐标轴 '+f(b)+' ms/°。新增条件 RT 差（有−无）：'+(x.rt!==null&&y.rt!==null?y.rt-x.rt:'—')+' ms。镜像试次另计正确率，不混入原始旋转斜率。';
 }
 if(s.experiment==='map')return '航向向上−北向上 RT 差：'+(g[0].rt!==null&&g[1].rt!==null?g[1].rt-g[0].rt:'—')+' ms；新增视野扇形−普通北向上 RT 差：'+(g[0].rt!==null&&g[2].rt!==null?g[2].rt-g[0].rt:'—')+' ms。负值表示更快。仅支持相对方向判断，不推断认知地图学习。';
 const stats=['road','panel'].map(priority=>{const rows=s.trials.filter(t=>!t.invalid&&t.priority===priority),areas=rows.reduce((a,t)=>{a.road+=(t.aoi.road||0)+(t.aoi.road_instrument||0);a.panel+=t.aoi.cargo_instrument||0;return a;},{road:0,panel:0});const total=areas.road+areas.panel;const base=summarize(rows.filter(t=>t.cond===0&&t.event!=='oncoming')),cue=summarize(rows.filter(t=>t.cond===1&&t.event!=='oncoming'));return (priority==='road'?'道路':'仪表')+'优先：道路采样占比 '+(total?Math.round(areas.road/total*100)+'%':'无有效眼动')+'；自适应−普通 RT 差 '+(base.rt!==null&&cue.rt!==null?cue.rt-base.rt:'—')+' ms';});
 const nogo=s.trials.filter(t=>!t.invalid&&t.event==='oncoming'),falseAlarms=nogo.filter(t=>!t.correct).length;return '对向火箭误响应 '+falseAlarms+'/'+nogo.length+'；本次奖励积分 '+s.trials.filter(t=>!t.invalid).reduce((n,t)=>n+(t.points||0),0)+'；'+stats.join('；')+'。道路采样占比仅在道路/仪表有效 AOI 样本内计算；不是完整 SEEV 模型拟合。';
}
function drawHeat(s){const c=$('#heat-canvas'),ctx=c.getContext('2d');c.width=800;c.height=300;for(const t of s.trials.filter(t=>!t.invalid))for(const p of t.gaze){if(p.x<0||p.x>1||p.y<0||p.y>1)continue;const x=p.x*c.width,y=p.y*c.height,g=ctx.createRadialGradient(x,y,0,x,y,18);g.addColorStop(0,'rgba(74,131,91,.025)');g.addColorStop(1,'rgba(74,131,91,0)');ctx.fillStyle=g;ctx.fillRect(x-18,y-18,36,36);}}
const uploadBusy=new Set();
function uploadStatuses(){try{return JSON.parse(localStorage.getItem('starparcel.upload-status')||'{}');}catch{return {};}}
async function sendCourse(s){if(!canUploadSession(s)||uploadBusy.has(s.id))return;const project=s.uploadProject||projectCode();if(!/^[A-Z0-9]{6}$/.test(project))throw Error('项目码无效');const states=uploadStatuses();if(states[s.id]?.state==='success'){$('#upload-state').textContent='已上传成功 · '+states[s.id].record;return;}uploadBusy.add(s.id);const button=$('#upload-session');if(button)button.disabled=true;const show=msg=>{if(location.hash==='#session/'+s.id&&$('#upload-state'))$('#upload-state').textContent=msg;};const save=x=>{const now=uploadStatuses();now[s.id]=x;localStorage.setItem('starparcel.upload-status',JSON.stringify(now));};let timedOut=false;const controller=new AbortController(),timeout=setTimeout(()=>{timedOut=true;controller.abort();},20000);try{save({state:'pending'});show('本机已保存，正在上传到项目 '+project+'…');const trials=flatRows(s).map(({session,participant,experiment,mode,created,display_rect,aoi,...rest})=>uploadTrial({...rest,session_id:session,aoi_summary:aoi}));const body={project,experiment:'starparcel_'+s.experiment+(s.protocol?.startsWith('starparcel-v4')?'_v4':s.protocol?.startsWith('starparcel-v3')?'_v3':s.protocol==='starparcel-v2-design-2026-11-02'?'_v2':'_v1'),participant:s.participant,condition:s.tier||'legacy',trials,meta:{protocol:s.protocol,collection_policy:s.collectionPolicy,session_id:s.id,tier:s.tier,planned_trials:s.plannedTrials,record_class:recordClass(s),course_eligible:s.courseEligible===true,calibration_error_gate:s.calibration?.errorGateEnabled??true,calibration_quality_flag:s.calibration?.qualityPass??null,calibration_error:s.calibration?.meanError}};if(new Blob([JSON.stringify(body)]).size>256*1024)throw Error('超过接口大小限制，请导出 JSON');const res=await fetch('https://attention-lab-production.up.railway.app/api/hw2/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});const result=await res.json();if(!res.ok||!result.ok)throw Error(result.msg||'服务器未确认');save({state:'success',record:result.record_id??'已保存',project});show('上传成功 · 项目 '+project+' · 记录 '+(result.record_id??'已保存'));}catch(e){const error=timedOut?'请求超时，是否已入库需到老师后台核验':e.message;try{save({state:'failed',error});}catch{}show('上传未确认：'+error+'。本机记录仍在；请先核验后台，再点击上传重试。');}finally{clearTimeout(timeout);uploadBusy.delete(s.id);if(button&&location.hash==='#session/'+s.id)button.disabled=false;}}
function confirmUpload(s){if(!canUploadSession(s))return;dialog('<h2>上传到课程项目</h2><p>将匿名编号、行为与眼动摘要发往课程项目 '+escape(s.uploadProject||projectCode())+'。请先核查后台，避免重复提交。</p><button class="primary" id="confirm-upload">确认上传</button>');$('#confirm-upload').onclick=()=>{modal.close();sendCourse(s);};}
function about(){app.innerHTML=`<div class="content-narrow"><section class="page-head"><div class="eyebrow">RESEARCH & CARE</div><h1>认真研究，也温柔探索。</h1><p>星际快递局是工程心理学的主题实验原型。三维模型由 Blender 制作，摄像头估计由 WebGazer 在本机运行。</p></section><div class="panel"><h3>三项研究来源</h3>${Object.values(studies).map(s=>`<div class="reference"><strong>${s.title} · ${s.source}</strong><p>${s.theory}</p><a href="${s.doi}" target="_blank" rel="noopener">打开原论文 DOI ↗</a></div>`).join('')}<p class="spaced">SEEV 与地图为课件推荐范围；心理旋转为新增经典研究。太空情境、试次数和改进条件属于课程项目改编，需明确区别于原论文。</p></div><div class="panel"><h3>数据与参与者</h3><p class="spaced">匿名编号、条件、按键、反应时、正确率及（正式模式下的）注视坐标保存在当前浏览器。摄像头画面只参与本机估计；关闭摄像头后停止采集。网页中的“关闭摄像头”可随时使用。</p><p class="spaced">开始任务前同意采集与上传后，完成记录自动发送行为试次和眼动摘要；失败可在结果页核验并手动重试。数据导出后请妥善保存；清除浏览器站点数据会移除本机记录。</p></div><div class="panel"><h3>当前版本的科学边界</h3><p class="spaced">本版本包含可玩的任务、练习、平衡条件、数据导出和校准流程。尚需真实参与者试测，确认普通摄像头误差、条件难度、帧率和模型性能；不预设显著结果。正式收数前须确认预测，并保留 Git 提交。</p><p class="spaced">没有伪造被试、原论文效应或全班数据。采样点的粗 AOI 归类不等同专业注视／扫视事件检测；动态刺激分析应结合导出的刺激区域和时间记录。</p></div></div>`;}
function route(){if(runner){runner.dispose();}disposeWorlds();const hash=location.hash.slice(1)||'home';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===hash||hash.startsWith('study')&&a.dataset.nav==='home'||hash.startsWith('session')&&a.dataset.nav==='results'));if(hash.startsWith('study/'))study(hash.split('/')[1]);else if(hash==='concepts')concepts();else if(hash==='results')results();else if(hash==='analysis')analysisPage(app);else if(hash.startsWith('session/'))sessionPage(hash.split('/')[1]);else if(hash==='about')about();else home();bindTier();window.scrollTo(0,0);}
window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>{eye.active=false;});route();eyeStatus();
